def fibonacci(n):
    if n <= 1:
        return n
    else:
        return fibonacci(n-1) + fibonacci(n-2)

def eh_primo(n):
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def ordenar_lista(lista):
    return sorted(lista)

# Exemplo
numeros = [3, 1, 4, 1, 5]
print(ordenar_lista(numeros))  # [1, 1, 3, 4, 5]

def fatorial(n):
    if n == 0 or n == 1:
        return 1
    else:
        return n * fatorial(n-1)

# Teste
print(fatorial(5))  # 120
